/**
 * App — Root component.
 * Sets up routing for Splash, Login, Location Permission, and the multi-page AppShell.
 */
import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { APIProvider } from '@vis.gl/react-google-maps';

import SplashScreen            from './components/screens/SplashScreen/SplashScreen';
import LoginScreen             from './components/screens/LoginScreen/LoginScreen';
import LocationPermissionScreen from './components/screens/LocationPermissionScreen/LocationPermissionScreen';
import ProtectedRoute          from './components/layout/ProtectedRoute/ProtectedRoute';
import ErrorBoundary           from './components/ErrorBoundary';

/* ── App Shell + BottomNavBar layout ── */
import AppShell from './components/layout/AppShell/AppShell';

/* ── Pages ── */
import NavigationPage from './pages/NavigationPage';
import HomePage       from './pages/HomePage';
import SafetyHubPage  from './pages/SafetyHubPage';
import CommunityPage  from './pages/CommunityPage';
import ProfilePage    from './pages/ProfilePage';

function App() {
  return (
    <APIProvider apiKey={import.meta.env.VITE_GOOGLE_MAPS_API_KEY} libraries={['places', 'visualization', 'marker']}>
      <BrowserRouter>
        <Routes>
          {/* ── Pre-app screens ── */}
          <Route path="/"         element={<SplashScreen />} />
          <Route path="/login"    element={<LoginScreen />} />
          <Route path="/location" element={<ProtectedRoute><LocationPermissionScreen /></ProtectedRoute>} />

          {/* ── Legacy route: redirect /map → /app/navigation ── */}
          <Route path="/map" element={<Navigate to="/app/navigation" replace />} />

          {/* ── Main application — nested under AppShell ── */}
          <Route
            path="/app"
            element={
              <ProtectedRoute>
                <ErrorBoundary>
                  <AppShell />
                </ErrorBoundary>
              </ProtectedRoute>
            }
          >
            {/* Default: go to home dashboard */}
            <Route index element={<Navigate to="home" replace />} />

            <Route path="navigation" element={<NavigationPage />} />
            <Route path="home"       element={<HomePage />} />
            <Route path="safety"     element={<SafetyHubPage />} />
            <Route path="community"  element={<CommunityPage />} />
            <Route path="profile"    element={<ProfilePage />} />
          </Route>

          {/* ── Fallback ── */}
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </BrowserRouter>
    </APIProvider>
  );
}

export default App;

import React from 'react';
import { AlertTriangle, ShieldAlert } from 'lucide-react';
import useAlertStore from '../../../stores/alertStore';
import useSosStore from '../../../stores/sosStore';
import SafePointSuggestions from '../../safety/SafePointSuggestions/SafePointSuggestions';
import './AlertModal.css';

const AlertModal = () => {
  const isModalVisible = useAlertStore((s) => s.isModalVisible);
  const hideModal = useAlertStore((s) => s.hideModal);
  const acknowledgeSafe = useAlertStore((s) => s.acknowledgeSafe);
  const activateSOSNow = useSosStore((s) => s.activateSOSNow);

  if (!isModalVisible) return null;

  const handleReturn = () => {
    hideModal();
  };

  const handleSafe = () => {
    acknowledgeSafe();
  };

  const handleAlert = () => {
    hideModal();
    // Trigger real SOS flow
    activateSOSNow();
  };

  return (
    <>
      {isModalVisible && (
        <div className="alert-modal-overlay">
        <div className="alert-modal-card">
          <div className="alert-modal-icon">
            <AlertTriangle size={32} strokeWidth={2.5} />
          </div>

          <h2 className="alert-modal-title">
            You have deviated from the recommended safe route.
          </h2>
          <p className="alert-modal-message">
            Would you like to return to the recommended route?
          </p>

          {/* Smart nearby safe point suggestions */}
          <SafePointSuggestions maxItems={3} />

          <div className="alert-modal-actions">
            <button className="alert-btn alert-btn-return" onClick={handleReturn}>
              Return to Route
            </button>
            <button className="alert-btn alert-btn-safe" onClick={handleSafe}>
              I'm Safe
            </button>
            <button className="alert-btn alert-btn-alert" onClick={handleAlert}>
              Send Alert
            </button>
          </div>
        </div>
      </div>
      )}

    </>
  );
};

export default AlertModal;

import React, { useEffect } from 'react';
import { ShieldAlert, Shield } from 'lucide-react';
import useAlertStore from '../../../stores/alertStore';
import useUiStore from '../../../stores/uiStore';
import useNavigationStore from '../../../stores/navigationStore';
import useRouteStore from '../../../stores/routeStore';
import { APP_MODES } from '../../../constants/appConstants';
import { closestPointOnRoute } from '../../../utils/geoUtils';
import './AlertMode.css';

const DEVIATION_THRESHOLD_METERS = 250;

const AlertMode = () => {
  const appMode = useUiStore((s) => s.appMode);
  const userPosition = useNavigationStore((s) => s.userPosition);

  // Use specific selectors for route store to prevent excessive re-renders
  const routes = useRouteStore((s) => s.routes);
  const activeRouteIndex = useRouteStore((s) => s.activeRouteIndex);

  const isAlertModeActive = useAlertStore((s) => s.isAlertModeActive);
  const toggleAlertMode = useAlertStore((s) => s.toggleAlertMode);
  const showModal = useAlertStore((s) => s.showModal);
  const isModalVisible = useAlertStore((s) => s.isModalVisible);
  const isCooldownActive = useAlertStore((s) => s.isCooldownActive);
  const clearCooldown = useAlertStore((s) => s.clearCooldown);

  // Monitor position for deviation
  useEffect(() => {
    if (!isAlertModeActive || appMode !== APP_MODES.NAVIGATING || isModalVisible || !userPosition) return;

    const currentRoute = routes[activeRouteIndex];
    if (!currentRoute || !currentRoute.geometry) return;

    // Use geoUtils to find distance
    const { distance } = closestPointOnRoute(userPosition, currentRoute.geometry);

    if (distance > DEVIATION_THRESHOLD_METERS) {
      if (!isCooldownActive) {
        showModal();
      }
    } else {
      if (isCooldownActive) {
        clearCooldown();
      }
    }
  }, [userPosition, isAlertModeActive, appMode, isModalVisible, isCooldownActive, routes, activeRouteIndex, showModal, clearCooldown]);

  // Bind simulateDeviation for hackathon demo (only in development)
  useEffect(() => {
    if (import.meta.env.DEV) {
      window.simulateDeviation = () => {
        if (appMode === APP_MODES.NAVIGATING) {
          clearCooldown();
          showModal();
          console.log("Simulated deviation triggered.");
        } else {
          console.warn("simulateDeviation: App must be in NAVIGATING mode.");
        }
      };
    }

    return () => {
      if (import.meta.env.DEV) {
        delete window.simulateDeviation;
      }
    };
  }, [appMode, showModal, clearCooldown]);

  // Alert Mode UI only exists during navigation
  if (appMode !== APP_MODES.NAVIGATING) {
    return null;
  }

  return (
    <button 
      className={`alert-mode-pill ${isAlertModeActive ? 'active' : ''}`}
      onClick={toggleAlertMode}
      aria-label="Toggle Alert Mode"
      aria-pressed={isAlertModeActive}
    >
      <span className="alert-mode-icon" aria-hidden="true">
        {isAlertModeActive ? '🟢' : '🛡'}
      </span>
      <span className="alert-mode-label">
        {isAlertModeActive ? 'Alert Mode Active' : 'Alert Mode'}
      </span>
    </button>
  );
};

export default AlertMode;

import React from 'react';
import { Users } from 'lucide-react';
import useContactStore from '../../../stores/contactStore';
import './EmergencyContactsButton.css';

const EmergencyContactsButton = () => {
  const setModalOpen = useContactStore((s) => s.setModalOpen);

  return (
    <button
      className="emergency-contacts-btn anim-scale-in"
      onClick={() => setModalOpen(true)}
      aria-label="Manage Emergency Contacts"
      title="Emergency Contacts"
    >
      <Users size={24} />
    </button>
  );
};

export default EmergencyContactsButton;

