import React, { useEffect, useState } from 'react';
import { X, UserPlus, Phone, User as UserIcon, Shield, Star, Trash2, Edit2, Check } from 'lucide-react';
import useContactStore from '../../../stores/contactStore';
import './EmergencyContactsModal.css';

const ContactForm = ({ initialData, onSubmit, onCancel, isLoading }) => {
  const [formData, setFormData] = useState({
    name: initialData?.name || '',
    phone: initialData?.phone || '',
    relationship: initialData?.relationship || 'Family',
    isPrimaryContact: initialData?.isPrimaryContact || false,
    isSOSContact: initialData?.isSOSContact ?? true,
  });

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value,
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onSubmit(formData);
  };

  return (
    <form className="ec-form" onSubmit={handleSubmit}>
      <div className="ec-form-row">
        <div className="ec-input-group">
          <UserIcon size={14} className="ec-input-icon" />
          <input
            type="text"
            name="name"
            placeholder="Name"
            value={formData.name}
            onChange={handleChange}
            required
          />
        </div>
        <div className="ec-input-group">
          <Phone size={14} className="ec-input-icon" />
          <input
            type="tel"
            name="phone"
            placeholder="Phone Number"
            value={formData.phone}
            onChange={handleChange}
            required
          />
        </div>
      </div>

      <div className="ec-form-row">
        <div className="ec-input-group">
          <select name="relationship" value={formData.relationship} onChange={handleChange}>
            <option value="Family">Family</option>
            <option value="Friend">Friend</option>
            <option value="Partner">Partner</option>
            <option value="Colleague">Colleague</option>
            <option value="Other">Other</option>
          </select>
        </div>
      </div>

      <div className="ec-form-toggles">
        <label className="ec-toggle-label">
          <input
            type="checkbox"
            name="isSOSContact"
            checked={formData.isSOSContact}
            onChange={handleChange}
          />
          <span className="ec-toggle-text">
            <Shield size={14} /> SOS Contact
          </span>
        </label>

        <label className="ec-toggle-label">
          <input
            type="checkbox"
            name="isPrimaryContact"
            checked={formData.isPrimaryContact}
            onChange={handleChange}
          />
          <span className="ec-toggle-text">
            <Star size={14} /> Primary Contact
          </span>
        </label>
      </div>

      <div className="ec-form-actions">
        {onCancel && (
          <button type="button" className="ec-btn-cancel" onClick={onCancel} disabled={isLoading}>
            Cancel
          </button>
        )}
        <button type="submit" className="ec-btn-submit" disabled={isLoading}>
          {isLoading ? 'Saving...' : initialData ? 'Update' : 'Add Contact'}
        </button>
      </div>
    </form>
  );
};

const ContactItem = ({ contact, onEdit, onDelete, isDeleting }) => {
  return (
    <div className="ec-item">
      <div className="ec-item-info">
        <div className="ec-item-header">
          <span className="ec-item-name">{contact.name}</span>
          <span className="ec-item-rel">({contact.relationship})</span>
        </div>
        <div className="ec-item-phone">{contact.phone}</div>
        <div className="ec-item-badges">
          {contact.isSOSContact && <span className="ec-badge sos"><Shield size={10} /> SOS</span>}
          {contact.isPrimaryContact && <span className="ec-badge primary"><Star size={10} /> Primary</span>}
        </div>
      </div>
      <div className="ec-item-actions">
        <button className="ec-icon-btn edit" onClick={() => onEdit(contact)} title="Edit">
          <Edit2 size={16} />
        </button>
        <button 
          className="ec-icon-btn delete" 
          onClick={() => onDelete(contact._id)} 
          disabled={isDeleting}
          title="Delete"
        >
          <Trash2 size={16} />
        </button>
      </div>
    </div>
  );
};

const EmergencyContactsModal = () => {
  const { 
    isModalOpen, setModalOpen, contacts, fetchContacts, 
    addContact, updateContact, deleteContact, isLoading, error 
  } = useContactStore();

  const [isAdding, setIsAdding] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [localError, setLocalError] = useState('');

  // Fetch contacts when modal opens
  useEffect(() => {
    if (isModalOpen) {
      fetchContacts();
      setIsAdding(false);
      setEditingId(null);
      setLocalError('');
    }
  }, [isModalOpen, fetchContacts]);

  if (!isModalOpen) return null;

  const handleClose = () => setModalOpen(false);

  const handleAddSubmit = async (data) => {
    setLocalError('');
    const res = await addContact(data);
    if (res.success) {
      setIsAdding(false);
    } else {
      setLocalError(res.message);
    }
  };

  const handleEditSubmit = async (id, data) => {
    setLocalError('');
    const res = await updateContact(id, data);
    if (res.success) {
      setEditingId(null);
    } else {
      setLocalError(res.message);
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm("Are you sure you want to remove this contact?")) {
      await deleteContact(id);
    }
  };

  return (
    <div className="ec-modal-overlay anim-fade-in" onClick={handleClose}>
      <div className="ec-modal-content anim-slide-up" onClick={(e) => e.stopPropagation()}>
        <div className="ec-modal-header">
          <div className="ec-modal-title">
            <Shield size={20} className="ec-title-icon" />
            <h2>Emergency Contacts</h2>
          </div>
          <button className="ec-close-btn" onClick={handleClose}>
            <X size={20} />
          </button>
        </div>

        <div className="ec-modal-body">
          {(error || localError) && (
            <div className="ec-error-banner">
              {error || localError}
            </div>
          )}

          {isLoading && !isAdding && !editingId && contacts.length === 0 ? (
            <div className="ec-loading">Loading contacts...</div>
          ) : (
            <>
              {/* Contact List */}
              <div className="ec-list">
                {contacts.length === 0 && !isAdding ? (
                  <div className="ec-empty-state">
                    <p>No emergency contacts added yet.</p>
                    <p className="ec-empty-sub">Add trusted friends or family to notify them during an SOS.</p>
                  </div>
                ) : (
                  contacts.map(contact => (
                    <React.Fragment key={contact._id}>
                      {editingId === contact._id ? (
                        <div className="ec-item-edit-wrapper">
                          <ContactForm 
                            initialData={contact}
                            onSubmit={(data) => handleEditSubmit(contact._id, data)}
                            onCancel={() => setEditingId(null)}
                            isLoading={isLoading}
                          />
                        </div>
                      ) : (
                        <ContactItem 
                          contact={contact} 
                          onEdit={(c) => { setIsAdding(false); setEditingId(c._id); }}
                          onDelete={handleDelete}
                          isDeleting={isLoading}
                        />
                      )}
                    </React.Fragment>
                  ))
                )}
              </div>

              {/* Add New Contact Form / Button */}
              {isAdding ? (
                <div className="ec-item-edit-wrapper mt-3">
                  <h4 className="ec-form-heading">Add New Contact</h4>
                  <ContactForm 
                    onSubmit={handleAddSubmit}
                    onCancel={() => setIsAdding(false)}
                    isLoading={isLoading}
                  />
                </div>
              ) : (
                !editingId && (
                  <button className="ec-add-btn" onClick={() => setIsAdding(true)}>
                    <UserPlus size={18} />
                    Add Contact
                  </button>
                )
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default EmergencyContactsModal;

/**
 * AppShell — Application layout wrapper.
 *
 * Renders the active page via <Outlet /> and keeps
 * the BottomNavBar persistent across all routes.
 *
 * This component is intentionally thin — no business logic.
 */
import React from 'react';
import { Outlet } from 'react-router-dom';
import BottomNavBar from '../BottomNavBar/BottomNavBar';
import './AppShell.css';

const AppShell = () => (
  <div className="app-shell">
    <main className="app-shell__content">
      <Outlet />
    </main>
    <BottomNavBar />
  </div>
);

export default AppShell;

/**
 * BottomNavBar — Persistent 5-tab bottom navigation.
 * Matches the existing SheShield dark glassmorphism design language.
 */
import React from 'react';
import { NavLink } from 'react-router-dom';
import { Home, Map, Shield, DoorOpen, User } from 'lucide-react';
import './BottomNavBar.css';

const TABS = [
  { to: '/app/home',       icon: Home,       label: 'Home' },
  { to: '/app/navigation', icon: Map,        label: 'Navigation' },
  { to: '/app/safety',     icon: Shield,     label: 'Safety Hub' },
  { to: '/app/community',  icon: DoorOpen,   label: 'Safety Rooms' },
  { to: '/app/profile',    icon: User,       label: 'Profile' },
];

const BottomNavBar = () => (
  <nav className="bottom-nav" aria-label="Main navigation">
    {TABS.map(({ to, icon: Icon, label }) => (
      <NavLink
        key={to}
        to={to}
        className={({ isActive }) =>
          `bottom-nav__item${isActive ? ' bottom-nav__item--active' : ''}`
        }
        aria-label={label}
      >
        <Icon className="bottom-nav__icon" aria-hidden="true" />
        <span className="bottom-nav__label">{label}</span>
        <span className="bottom-nav__indicator" aria-hidden="true" />
      </NavLink>
    ))}
  </nav>
);

export default BottomNavBar;

/**
 * MapShell — Root layout orchestrator.
 *
 * Responsibilities:
 *   1. Calls useGeolocation() ONCE — stores position in navigationStore.
 *      All other components read from the store, never call geolocation again.
 *   2. Positions all floating UI layers over the map using CSS.
 *   3. Remains a pure layout component — no business logic here.
 */
import { useEffect } from 'react';
import { Shield } from 'lucide-react';
import { haversineDistance } from '../../../utils/geoUtils';

import MapContainer    from '../../map/MapContainer/MapContainer';
import SearchBar       from '../../search/SearchBar/SearchBar';
import SOSButton       from '../../sos/SOSButton/SOSButton';
import BottomSheet     from '../../ui/BottomSheet/BottomSheet';
import MapControls     from '../../ui/MapControls/MapControls';
import MapLayerControls from '../../ui/MapLayerControls/MapLayerControls';
import AlertMode       from '../../alert/AlertMode/AlertMode';
import AlertModal      from '../../alert/AlertModal/AlertModal';
import ReportButton    from '../../report/ReportButton/ReportButton';
import ReportModal     from '../../report/ReportModal/ReportModal';
import LiveReportsFeed from '../../report/LiveReportsFeed/LiveReportsFeed';
import FindSafeSpotButton from '../../safety/FindSafeSpotButton/FindSafeSpotButton';

import useGeolocation    from '../../../hooks/useGeolocation';
import useNavigationStore from '../../../stores/navigationStore';
import useSafetyStore from '../../../stores/safetyStore';
import useReportStore from '../../../stores/reportStore';
import useJourneyTracker from '../../../hooks/useJourneyTracker';
import useUiStore from '../../../stores/uiStore';
import axiosInstance from '../../../services/api/axiosInstance';
import { APP_MODES } from '../../../constants/appConstants';

import './MapShell.css';

const MapShell = () => {
  const appMode = useUiStore((s) => s.appMode);
  /* Single geolocation call for the entire app */
  const { position } = useGeolocation(appMode === APP_MODES.NAVIGATING);
  const updatePosition = useNavigationStore((s) => s.updatePosition);

  const setHeatMapData = useSafetyStore((s) => s.setHeatMapData);
  const setSafePoints = useSafetyStore((s) => s.setSafePoints);
  const setLoadingHeatMap = useSafetyStore((s) => s.setLoadingHeatMap);
  const setLoadingSafePoints = useSafetyStore((s) => s.setLoadingSafePoints);
  const setSafePointsError = useSafetyStore((s) => s.setSafePointsError);

  const setReports = useReportStore((s) => s.setReports);

  // Activate journey tracker hook (runs only in NAVIGATING mode)
  useJourneyTracker();

  useEffect(() => {
    if (position) {
      updatePosition([position.lat, position.lng]);
    }
  }, [position, updatePosition]);

  // Fetch real safety data from backend when position is available
  useEffect(() => {
    const fetchSafetyData = async () => {
      if (!position) return;

      setLoadingHeatMap(true);
      setLoadingSafePoints(true);

      try {
        const params = { latitude: position.lat, longitude: position.lng, radius: 5000 };

        // 1. Fetch heatmap data independently so errors here don't block other layers
        let heatmap = [];
        try {
          const heatmapRes = await axiosInstance.get('/heatmap');
          heatmap = (heatmapRes.data?.points || []).map((p) => [
            p.latitude,
            p.longitude,
            p.weight / 5,
          ]);
        } catch (heatmapError) {
          console.error('Failed to fetch heatmap data', heatmapError);
        }
        setHeatMapData(heatmap);

        // 2. Fetch other safety data
        const [pointsRes, incidentsRes] = await Promise.all([
          axiosInstance.get('/safe-points', { params }),
          axiosInstance.get('/incidents', { params }),
        ]);

        // Normalization moved out since it's already extracted above

        // Normalize safe points: backend category string → frontend type id
        const CATEGORY_TO_TYPE = {
          'Police Station':    'police',
          'Hospital':          'hospital',
          'Pharmacy':          'pharmacy',
          'Petrol Pump':       'petrol_pump',
          'Hotel':             'hotel',
          'Metro Station':     'metro',
          'Railway Station':   'railway',
          'Bus Terminal':      'bus_stand',
          'Women Help Centre': 'womens_desk',
        };
        const points = (pointsRes.data?.safePoints || [])
          .map((p) => {
            // Fallback to GeoJSON location if latitude/longitude are missing from old DB records
            const rawLat = p.latitude ?? p.location?.coordinates?.[1];
            const rawLng = p.longitude ?? p.location?.coordinates?.[0];
            const pLat = parseFloat(rawLat);
            const pLng = parseFloat(rawLng);

            if (Number.isNaN(pLat) || Number.isNaN(pLng)) {
              return null; // Invalid coordinate
            }

            const distance = Math.round(haversineDistance([position.lat, position.lng], [pLat, pLng]));

            return {
              ...p,
              id:       p._id,
              type:     CATEGORY_TO_TYPE[p.category] || 'hotel',
              lat:      pLat,
              lng:      pLng,
              isOpen24h: p.openStatus?.toLowerCase().includes('24'),
              distance: distance
            };
          })
          .filter(Boolean); // Remove invalid points

        setSafePoints(points);

        // Normalize incidents to match the frontend reportStore shape
        const reports = (incidentsRes.data?.incidents || []).map((inc) => ({
          id:          inc._id,
          category:    inc.type,
          description: inc.description || '',
          position:    inc.latitude != null ? [inc.latitude, inc.longitude] : null,
          timestamp:   inc.createdAt,
        })).filter((r) => r.position !== null);
        setReports(reports);

      } catch (error) {
        console.error('Failed to fetch safety data', error);
        setSafePointsError('Failed to load nearby safe points. Please check your connection.');
      } finally {
        setLoadingHeatMap(false);
      }
    };

    fetchSafetyData();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [position?.lat, position?.lng]); // fetch once per position change

  return (
    <div className="map-shell" id="she-app-shell">

      {/* ── Layer 0: Full-screen map (z-index: 0) ── */}
      <div className="layer layer--map">
        <MapContainer />
      </div>

      {/* ── Layer 1: Top floating controls (z-index: 100) ── */}
      <div className="layer layer--top" aria-label="Search">
        <div className="top-controls-wrap">
          {/* Search */}
          <div style={{ display: 'flex', alignItems: 'center' }}>
            <SearchBar />
          </div>

          {/* ── Live Reports Feed ── */}
          <LiveReportsFeed />
        </div>
      </div>

      {/* ── Layer 2: Right-side map controls (z-index: 150) ── */}
      <div className="layer layer--controls" aria-label="Map controls">
        <MapLayerControls />
        <MapControls />
