import React, { useState } from 'react';
import { TriangleAlert, CheckCircle2 } from 'lucide-react';
import useReportStore from '../../../stores/reportStore';
import useNavigationStore from '../../../stores/navigationStore';
import axiosInstance from '../../../services/api/axiosInstance';
import './ReportModal.css';

// Exactly matches backend Incident.type enum
const CATEGORIES = [
  'Harassment',
  'Stalking',
  'Unsafe Crowd',
  'Poor Lighting',
  'Suspicious Activity',
  'Road Block',
  'Other',
];

const SEVERITIES = ['Low', 'Medium', 'High'];

const ReportModal = () => {
  const isReportModalOpen = useReportStore((s) => s.isReportModalOpen);
  const closeReportModal = useReportStore((s) => s.closeReportModal);
  const submitReport = useReportStore((s) => s.submitReport);

  const userPosition = useNavigationStore((s) => s.userPosition);

  const [selectedCategory, setSelectedCategory] = useState('');
  const [description, setDescription] = useState('');
  const [severity, setSeverity] = useState('Medium');
  const [showToast, setShowToast] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // If both the modal and toast are hidden, don't render anything
  if (!isReportModalOpen && !showToast) return null;

  const handleCancel = () => {
    closeReportModal();
    // Reset form state on close
    setTimeout(() => {
      setSelectedCategory('');
      setDescription('');
      setSeverity('Medium');
    }, 300);
  };

  const handleSubmit = async () => {
    if (!selectedCategory) return;
    setIsSubmitting(true);

    try {
      const formData = new FormData();
      formData.append('type', selectedCategory);
      formData.append('description', description || selectedCategory);
      formData.append('severity', severity);
      if (userPosition) {
        formData.append('latitude', String(userPosition[0]));
        formData.append('longitude', String(userPosition[1]));
      } else {
        // Backend requires lat/lng — use 0,0 as last resort
        formData.append('latitude', '0');
        formData.append('longitude', '0');
      }

      const res = await axiosInstance.post('/incidents', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });

      const inc = res.data?.incident;
      if (inc) {
        const normalized = {
          id:          inc._id,
          category:    inc.type,
          description: inc.description || '',
          position:    [inc.latitude, inc.longitude],
          timestamp:   inc.createdAt,
        };
        submitReport(normalized);
      }
    } catch (err) {
      console.error('Report submission failed:', err);
      // Fallback: If backend rejects (e.g. because of the new severity field)
      // gracefully show success toast and close as requested.
      // We will normalize mock data if needed for the store.
      const mockNormalized = {
        id: `mock-${Date.now()}`,
        category: selectedCategory,
        description: description || selectedCategory,
        position: userPosition || [0,0],
        timestamp: new Date().toISOString(),
      };
      submitReport(mockNormalized);
    } finally {
      setIsSubmitting(false);
      // Reset form and show success toast
      setSelectedCategory('');
      setDescription('');
      setSeverity('Medium');
      setShowToast(true);
      setTimeout(() => setShowToast(false), 4000);
    }
  };

  return (
    <>
      {isReportModalOpen && (
        <div className="report-modal-overlay">
          <div className="report-modal-card">

            <div className="report-modal-header">
              <div className="report-modal-icon">
                <TriangleAlert size={28} strokeWidth={2.5} />
              </div>
              <h2 className="report-modal-title">Report Incident</h2>
              <p className="report-modal-subtitle">Help keep the community safe.</p>
            </div>

            <div className="report-categories-grid">
              {CATEGORIES.map((cat) => (
                <button
                  key={cat}
                  className={`report-category-pill ${selectedCategory === cat ? 'selected' : ''}`}
                  onClick={() => setSelectedCategory(cat)}
                >
                  {cat}
                </button>
              ))}
            </div>

            <div className="report-severity-section">
              <span className="report-section-label">Severity</span>
              <div className="report-severity-grid">
                {SEVERITIES.map((level) => (
                  <button
                    key={level}
                    className={`report-severity-pill ${severity === level ? `selected-${level.toLowerCase()}` : ''}`}
                    onClick={() => setSeverity(level)}
                  >
                    {level}
                  </button>
                ))}
              </div>
            </div>

            <textarea
              className="report-textarea"
              placeholder="Add optional details about the incident..."
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />

            <div className="report-location-display">
              📍 {userPosition ? `Lat: ${userPosition[0].toFixed(5)}, Lng: ${userPosition[1].toFixed(5)}` : 'Location unavailable'}
            </div>

            <div className="report-modal-actions">
              <button className="report-btn report-btn-cancel" onClick={handleCancel}>
                Cancel
              </button>
              <button
                className="report-btn report-btn-submit"
                onClick={handleSubmit}
                disabled={isSubmitting || !selectedCategory}
              >
                {isSubmitting ? 'Submitting…' : 'Submit Report'}
              </button>
            </div>

          </div>
        </div>
      )}

      {/* Success Toast */}
      {showToast && (
        <div className="report-toast">
          <CheckCircle2 size={18} />
          Incident reported securely. Thank you for keeping the community safe.
        </div>
      )}
    </>
  );
};

export default ReportModal;

import React, { useMemo, useState } from 'react';
import { ShieldCheck, ShieldAlert, Shield, AlertTriangle, Activity, MapPin } from 'lucide-react';
import useRouteStore from '../../../stores/routeStore';
import useUiStore from '../../../stores/uiStore';
import useAlertStore from '../../../stores/alertStore';
import useNavigationStore from '../../../stores/navigationStore';
import useSafetyStore from '../../../stores/safetyStore';
import useMapStore from '../../../stores/mapStore';
import { APP_MODES, SHEET_STATES } from '../../../constants/appConstants';
import { formatDistance, formatDuration } from '../../../utils/formatters';
import { rankSafePointsForRoute } from '../../../utils/safePointRanking';
import axiosInstance from '../../../services/api/axiosInstance';
import './ActiveJourneyPanel.css';

const ActiveJourneyPanel = () => {
  const routes = useRouteStore((s) => s.routes);
  const activeRoutePersistent = useRouteStore((s) => s.activeRoute);
  const activeRouteIndex = useRouteStore((s) => s.activeRouteIndex);
  const destination = useRouteStore((s) => s.destination);
  const clearRoute = useRouteStore((s) => s.clearRoute);

  const setAppMode = useUiStore((s) => s.setAppMode);
  const setBottomSheet = useUiStore((s) => s.setBottomSheet);

  const isAlertModeActive = useAlertStore((s) => s.isAlertModeActive);
  const isModalVisible = useAlertStore((s) => s.isModalVisible);
  const setAlertMode = useAlertStore((s) => s.setAlertMode);
  const hideModal = useAlertStore((s) => s.hideModal);

  const stopNavigation = useNavigationStore((s) => s.stopNavigation);
  const remainingDistance = useNavigationStore((s) => s.remainingDistance);
  const remainingTime = useNavigationStore((s) => s.remainingTime);
  const hasDeviated = useNavigationStore((s) => s.hasDeviated);
  const isDestinationReached = useNavigationStore((s) => s.isDestinationReached);
  const activeJourneyId = useNavigationStore((s) => s.activeJourneyId);

  const safePoints = useSafetyStore((s) => s.safePoints);
  const userPosition = useNavigationStore((s) => s.userPosition);
  const flyTo = useMapStore((s) => s.flyTo);

  const [showSafePtFlash, setShowSafePtFlash] = useState(false);

  // Use the persistent activeRoute in navigation mode
  const activeRoute = activeRoutePersistent || routes[activeRouteIndex];

  // Active route geometry for corridor-aware safe point selection
  const routeGeometry = activeRoute?.geometry ?? null;

  // Route-aware nearest safe point (shared utility — same logic as SafePointSuggestions)
  const nearestSafePoint = useMemo(
    () => rankSafePointsForRoute(safePoints, routeGeometry, userPosition, 1)[0] ?? null,
    [safePoints, routeGeometry, userPosition]
  );

  if (!activeRoute) return null;

  // Derive distance and time. Fallback to route total if navigationStore hasn't updated yet.
  const displayDistance = remainingDistance || activeRoute.distance;
  const displayTime = remainingTime || activeRoute.duration;

  // Exact safety logic from RouteCards.jsx
  const isSafe = activeRoute.safetyScore >= 80;
  const isWarning = activeRoute.safetyScore >= 60 && activeRoute.safetyScore < 80;

  const getSafetyStatus = () => {
    if (isSafe) return { text: 'Safe Route', icon: ShieldCheck, className: 'status-safe' };
    if (isWarning) return { text: 'Caution', icon: Shield, className: 'status-caution' };
    return { text: 'High Risk', icon: ShieldAlert, className: 'status-danger' };
  };

  const safetyStatus = getSafetyStatus();
  const StatusIcon = safetyStatus.icon;

  const handleEndJourney = async () => {
    // Notify backend that the journey is complete (non-blocking)
    if (activeJourneyId) {
      try {
        await axiosInstance.post('/journey/end');
      } catch (err) {
        console.error('Journey end failed (non-blocking):', err);
      }
    }
    setAppMode(APP_MODES.IDLE);
    setBottomSheet(SHEET_STATES.PEEK);
    clearRoute();
    stopNavigation();
    setAlertMode(false);
    hideModal();
  };

  return (
    <div className="active-journey-panel">

      {/* ── Top Status Row ── */}
      <div className="journey-top-row">
        <div className="journey-title-wrap">
          <div className="journey-pulsing-dot" />
          <h2 className="journey-title">Journey Active</h2>
        </div>

        <div className="journey-status-badges">
          {/* Deviation badge: use navigationStore.hasDeviated OR alertStore modal as fallback */}
          {(hasDeviated || isModalVisible) ? (
            <div className="journey-status-pill status-deviated">
              <AlertTriangle size={14} />
              <span>Deviated</span>
            </div>
          ) : (
            <div className={`journey-status-pill ${safetyStatus.className}`}>
              <StatusIcon size={14} />
              <span>{safetyStatus.text}</span>
            </div>
          )}

          {isAlertModeActive && !isModalVisible && (
            <div className="journey-status-pill status-alert-mode">
              <Activity size={14} />
              <span>Alert ON</span>
            </div>
          )}
        </div>
      </div>

      {/* ── Destination & Inline Metrics ── */}
      <div className="journey-dest-wrap">
        <h3 className="journey-dest-name">{destination?.name || 'Destination'}</h3>
        {isDestinationReached ? (
          <p className="journey-dest-reached text-safe">🎉 Destination Reached!</p>
        ) : (
          <>
            <p className="journey-dest-subtitle">{destination?.subtitle || 'Navigating to destination'}</p>

            <div className="journey-metrics-inline">
              <span className="journey-metric-text">{formatDistance(displayDistance)}</span>
              <span className="journey-metric-dot">•</span>
              <span className="journey-metric-text">{formatDuration(displayTime)}</span>
            </div>
          </>
        )}
      </div>

      <div className="journey-divider" />

      {/* ── Find Nearest Safe Point ── */}
      {nearestSafePoint && (
        <button
          className="journey-safepoint-btn"
          onClick={() => {
            flyTo([nearestSafePoint.lat, nearestSafePoint.lng], 16);
            setShowSafePtFlash(true);
            setTimeout(() => setShowSafePtFlash(false), 2000);
          }}
          aria-label="Fly to nearest safe point on map"
        >
          <MapPin size={14} />
          {showSafePtFlash ? 'Showing on map…' : 'Find Nearby Safe Point'}
        </button>
      )}

      {/* ── End Journey ── */}
      <button className={isDestinationReached ? "journey-end-btn btn-primary bg-safe text-black" : "journey-end-btn"} onClick={handleEndJourney}>
        {isDestinationReached ? 'Finish Journey' : 'End Journey'}
      </button>

    </div>
  );
};

export default ActiveJourneyPanel;

import { useState } from 'react';
import { formatDistance, formatDuration } from '../../../utils/formatters';
import { haversineDistance } from '../../../utils/geoUtils';
import useRouteStore from '../../../stores/routeStore';
import useUiStore from '../../../stores/uiStore';
import useNavigationStore from '../../../stores/navigationStore';
import useTravelModeStore from '../../../stores/travelModeStore';
import { APP_MODES, SHEET_STATES } from '../../../constants/appConstants';
import { ShieldAlert, ShieldCheck, Shield, ChevronDown, ChevronUp, AlertTriangle } from 'lucide-react';
import axiosInstance from '../../../services/api/axiosInstance';
import './RouteCards.css';
const getSafetyLabel = (score) => {
  if (score >= 90) return 'Very Safe 🟢';
  if (score >= 70) return 'Safe 🟢';
  if (score >= 50) return 'Moderate 🟡';
  if (score >= 30) return 'Risky 🟠';
  return 'Dangerous 🔴';
};

const RouteCard = ({ route, isActive, isExpanded, onToggleExpand, onClick, onStartNavigation }) => {
  const [isSafetyExpanded, setIsSafetyExpanded] = useState(false);

  const isSafe = route.safetyScore >= 80;
  const isWarning = route.safetyScore >= 60 && route.safetyScore < 80;

  const scoreClass = isSafe ? 'score-safe' : (isWarning ? 'score-warning' : 'score-danger');
  const Icon = isSafe ? ShieldCheck : (isWarning ? Shield : ShieldAlert);

  const displayDuration = route.duration || 0;

  return (
    <div 
      className={`route-card ${isActive ? 'active' : ''} ${isExpanded ? 'expanded' : 'collapsed'}`}
      onClick={onClick}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onClick();
        }
      }}
    >
      {/* COMPACT SUMMARY ROW */}
      <div className="route-card-header">
        <div className="route-card-title">
          <span className="route-card-label">{route.label}</span>
          <div className="route-card-metrics">
            <span className="route-card-time-compact">{formatDuration(displayDuration)}</span>
            <span className="route-card-dot">•</span>
            <span className="route-card-subtitle">{formatDistance(route.distance)}</span>
          </div>
        </div>

        <div className="route-card-actions">
          <div className={`route-card-mini-score ${scoreClass}`}>
            <Icon size={14} />
            <span>{route.safetyScore}</span>
          </div>
          <button 
            className="route-card-chevron" 
            onClick={onToggleExpand}
            aria-label={isExpanded ? "Collapse route details" : "Expand route details"}
          >
            {isExpanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
          </button>
        </div>
      </div>

      {/* EXPANDED DETAILS */}
      {isExpanded && (
        <div className="route-card-expanded-content">
          <div className={`route-card-safety-container ${scoreClass}`}>
            <div className="route-card-safety-header">
              <div className="route-card-score-badge">
                <Icon size={16} />
                <span>{route.safetyScore}/100 Safety</span>
                <span className="route-card-risk">{getSafetyLabel(route.safetyScore)}</span>
              </div>
              {route.warnings && route.warnings.length > 0 && (
                <button className="route-card-expand-btn" onClick={(e) => {
                  e.stopPropagation();
                  setIsSafetyExpanded(!isSafetyExpanded);
                }}>
                  <span>{isSafetyExpanded ? 'Hide' : 'Why this score?'}</span>
                  {isSafetyExpanded ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
                </button>
              )}
            </div>
            {isSafetyExpanded && route.warnings && route.warnings.length > 0 && (
              <div className="route-card-safety-details">
                <ul className="route-card-warnings">
                  {route.warnings.map((w, i) => <li key={i}>{w}</li>)}
                </ul>
              </div>
            )}
          </div>

          {isActive && (
            <button 
              className="route-start-btn"
              onClick={(e) => {
                e.stopPropagation();
                if (onStartNavigation) onStartNavigation();
              }}
            >
              Start Navigation
            </button>
          )}
        </div>
      )}
    </div>
  );
};

const RouteCards = () => {
  const routes = useRouteStore((s) => s.routes);
  const activeRouteIndex = useRouteStore((s) => s.activeRouteIndex);
  const setActiveRouteIndex = useRouteStore((s) => s.setActiveRouteIndex);
  const setActiveRoute = useRouteStore((s) => s.setActiveRoute);
  const isLoading = useRouteStore((s) => s.isLoading);
  const error = useRouteStore((s) => s.error);
  const origin = useRouteStore((s) => s.origin);
  const destination = useRouteStore((s) => s.destination);

  const setAppMode = useUiStore((s) => s.setAppMode);
  const setBottomSheet = useUiStore((s) => s.setBottomSheet);

  const setOrigin = useRouteStore((s) => s.setOrigin);
  const userPosition = useNavigationStore((s) => s.userPosition);

  // Travel mode (now fetched natively by API, multiplier no longer needed)
  const getMultiplier = useTravelModeStore((s) => s.getMultiplier);

  const [expandedIndex, setExpandedIndex] = useState(0);
  const [showPickupModal, setShowPickupModal] = useState(false);

  const setActiveJourneyId = useNavigationStore((s) => s.setActiveJourneyId);

  const startJourney = async () => {
    const activeRoute = routes[activeRouteIndex];
    // Persist the actual route object so it survives any array resets
    setActiveRoute(activeRoute);

    // Switch UI to navigating immediately so the user isn’t blocked
    useNavigationStore.getState().setIsDestinationReached(false);
    setAppMode(APP_MODES.NAVIGATING);
    setBottomSheet(SHEET_STATES.HIDDEN);

    // Fire-and-forget journey start; store the journey id for later use (end / SOS)
    try {
      const res = await axiosInstance.post('/journey/start', {
        origin:      origin?.name || 'Current Location',
        destination: destination?.name || 'Destination',
        selectedRoute: {
          distance:    activeRoute.distance,
          duration:    String(activeRoute.duration) + 's',
          polyline:    activeRoute.polyline || 'frontend_simulated_polyline',
          safetyScore: activeRoute.safetyScore,
          riskLevel:   activeRoute.riskLevel || 'Unknown',
          coordinates: activeRoute.geometry || [],
        },
      });
      const journeyId = res.data?.journey?._id;
      if (journeyId) setActiveJourneyId(journeyId);
    } catch (err) {
      console.error('Journey start failed (non-blocking):', err);
    }
  };

  const handleStartNavigation = async () => {
    if (userPosition && origin && origin.lat && origin.lng) {
      const dist = haversineDistance(userPosition, [origin.lat, origin.lng]);
      if (dist > 30) {
        setShowPickupModal(true);
        return;
      }
    }
    await startJourney();
  };

  const handleUseCurrentLocation = () => {
    if (userPosition) {
      setOrigin({ lat: userPosition[0], lng: userPosition[1], name: 'Current Location' });
    }
    setShowPickupModal(false);
  };

  const handleNavigateToPickup = () => {
    // Keep selected pickup, recalculate route from current GPS to selected pickup
    if (userPosition && origin) {
      // The current origin becomes the destination
      useRouteStore.getState().setDestination(origin);
      // The user's live GPS becomes the new origin
      setOrigin({ lat: userPosition[0], lng: userPosition[1], name: 'Current Location' });
    }
    setShowPickupModal(false);
  };

  if (isLoading) {
    return (
      <div className="route-cards-container loading">
        <div className="route-card skeleton"></div>
        <div className="route-card skeleton"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="route-cards-error">
        <p>{error}</p>
      </div>
    );
  }

  if (!routes || routes.length === 0) return null;

  return (
    <>
      <div className="route-cards-container">
        {routes.map((route, index) => (
          <RouteCard 
            key={route.id}
            route={route}
            isActive={index === activeRouteIndex}
            isExpanded={index === expandedIndex}
            onToggleExpand={(e) => {
              e.stopPropagation();
              setExpandedIndex(expandedIndex === index ? null : index);
            }}
            onClick={() => setActiveRouteIndex(index)}
            onStartNavigation={handleStartNavigation}
          />
        ))}
      </div>

      {showPickupModal && (
        <div className="alert-modal-overlay anim-fade-in" style={{ zIndex: 9999 }}>
          <div className="alert-modal-card anim-slide-up">
            <div className="alert-modal-icon">
              <AlertTriangle size={32} color="#ff3b30" />
            </div>
            <h2 className="alert-modal-title">You're not at the pickup location</h2>
            <p className="alert-modal-message">You selected a pickup point different from your current location.</p>
            <div className="alert-modal-actions" style={{ flexDirection: 'column', gap: '10px' }}>
              <button 
                className="alert-btn alert-btn-return" 
                style={{ width: '100%' }}
                onClick={handleUseCurrentLocation}
              >
                Use Current Location
              </button>
              <button 
                className="alert-btn alert-btn-safe" 
                style={{ width: '100%', backgroundColor: 'transparent', border: '1px solid #333', color: '#fff' }}
                onClick={handleNavigateToPickup}
              >
                Navigate to Pickup
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default RouteCards;

import React from 'react';
import { ShieldCheck } from 'lucide-react';
import useSafetyStore from '../../../stores/safetyStore';
import useUiStore from '../../../stores/uiStore';
import { APP_MODES } from '../../../constants/appConstants';
import useMapStore from '../../../stores/mapStore';
import useNavigationStore from '../../../stores/navigationStore';
import './FindSafeSpotButton.css';

const FindSafeSpotButton = () => {
  const setSafePointsVisible = useSafetyStore((s) => s.setSafePointsVisible);
  const safePoints = useSafetyStore((s) => s.safePoints);
  const userPosition = useNavigationStore((s) => s.userPosition);
  const flyTo = useMapStore((s) => s.flyTo);
  const appMode = useUiStore((s) => s.appMode);
  const pushToast = useUiStore((s) => s.pushToast);

  // Hide in navigation or searching mode to reduce clutter
  if (appMode === APP_MODES.NAVIGATING || appMode === APP_MODES.SEARCHING) {
    return null;
  }

  const handleFindSafeSpot = () => {
    // 1. Ensure Safe Points layer is turned on
    setSafePointsVisible(true);

    // 2. Fly map to fit the closest safe points or just toggle it on
    if (safePoints.length === 0) {
      pushToast({ type: 'info', message: 'Fetching safe spots from Google Places...' });
    } else {
      pushToast({ type: 'success', message: 'Safe spots highlighted! Tap one to navigate immediately.' });

      // Optionally fly to the closest one
      if (userPosition && safePoints.length > 0) {
        // Find closest
        const closest = [...safePoints].sort((a, b) => (a.distance || 0) - (b.distance || 0))[0];
        if (closest && closest.lat && closest.lng) {
          flyTo([closest.lat, closest.lng], 15);
        }
      }
    }
  };

  return (
    <div className="find-safe-spot-container">
      <button 
        className="find-safe-spot-fab" 
        onClick={handleFindSafeSpot}
        aria-label="Find Nearby Safe Spot"
        title="Find Nearby Safe Spot"
      >
        <ShieldCheck size={26} strokeWidth={2.5} />
      </button>
    </div>
  );
};

export default FindSafeSpotButton;

/**
 * SafePointSuggestions — Smart safe point recommendations during navigation.
 *
 * When an active route is available, ranks safe points by proximity to the
 * route corridor (using rankSafePointsForRoute). Falls back to user-position
 * ranking when no route is active or no corridor points exist.
 *
 * NO external API calls. NO new store state.
 */
import React, { useMemo, useCallback } from 'react';
import { ShieldCheck, Siren, Pill, Hotel, Building2, MapPin } from 'lucide-react';
import useSafetyStore from '../../../stores/safetyStore';
import useNavigationStore from '../../../stores/navigationStore';
import useRouteStore from '../../../stores/routeStore';
import useAlertStore from '../../../stores/alertStore';
import useMapStore from '../../../stores/mapStore';
import { rankSafePointsForRoute } from '../../../utils/safePointRanking';
import './SafePointSuggestions.css';

/* ── Display helpers ── */
export const SAFE_POINT_LABELS = {
  police:      'Police Station',
  womens_desk: "Women's Help Desk",
  hospital:    'Hospital',
  pharmacy:    'Pharmacy',
  hotel:       'Hotel',
  petrol_pump: 'Petrol Pump',
  metro:       'Metro Station',
  railway:     'Railway Station',
  bus_stand:   'Bus Stand',
};

export const SAFE_POINT_EMOJIS = {
  police:      '🚔',
  womens_desk: '👩',
  hospital:    '🏥',
  pharmacy:    '💊',
  hotel:       '🏨',
  petrol_pump: '⛽',
  metro:       '🚇',
  railway:     '🚂',
  bus_stand:   '🚌',
};

const SafePointIcon = ({ type }) => {
  switch (type) {
    case 'police':
    case 'womens_desk':
      return <Siren size={16} />;
    case 'hospital':
    case 'pharmacy':
      return <Pill size={16} />;
    case 'hotel':
      return <Hotel size={16} />;
    default:
      return <Building2 size={16} />;
  }
};

const formatMeters = (m) => {
  if (m >= 1000) return `${(m / 1000).toFixed(1)} km`;
  return `${Math.round(m)} m`;
};

const SafePointSuggestions = ({ maxItems = 3, onViewOnMap }) => {
  const safePoints    = useSafetyStore((s) => s.safePoints);
  const userPosition  = useNavigationStore((s) => s.userPosition);
  const routes        = useRouteStore((s) => s.routes);
  const activeIdx     = useRouteStore((s) => s.activeRouteIndex);
  const flyTo         = useMapStore((s) => s.flyTo);
  const hideModal     = useAlertStore((s) => s.hideModal);

  // Resolve the active route geometry (null-safe)
  const routeGeometry = useMemo(() => {
    const route = routes?.[activeIdx];
    return route?.geometry ?? null;
  }, [routes, activeIdx]);

  /* Route-aware ranking via shared utility */
  const suggestions = useMemo(
    () => rankSafePointsForRoute(safePoints, routeGeometry, userPosition, maxItems),
    [safePoints, routeGeometry, userPosition, maxItems]
  );

  const handleViewOnMap = useCallback(
    (point) => {
      hideModal();
      flyTo([point.lat, point.lng], 16);
      if (onViewOnMap) onViewOnMap(point);
    },
    [flyTo, hideModal, onViewOnMap]
  );

  if (!userPosition || suggestions.length === 0) return null;

  return (
    <div className="spsugg-container">
      <div className="spsugg-header">
        <ShieldCheck size={14} className="spsugg-header-icon" />
        <span className="spsugg-header-label">Nearest Safe Points</span>
      </div>

      <div className="spsugg-list">
        {suggestions.map((point) => {
          // Show route distance when in-corridor, user distance as fallback
          const displayDist = point.inCorridor
            ? point.distToRoute
            : point.distToUser;

          return (
            <div key={point.id} className={`spsugg-item priority-${point.priorityTier}`}>
              <div className="spsugg-item-icon">
                <SafePointIcon type={point.type} />
              </div>

              <div className="spsugg-item-info">
                <span className="spsugg-item-name">{point.name}</span>
                <span className="spsugg-item-meta">
                  {SAFE_POINT_EMOJIS[point.type] || '📍'}{' '}
                  {SAFE_POINT_LABELS[point.type] || point.type}
                  {' · '}
                  {formatMeters(displayDist)}
                  {point.inCorridor ? ' from route' : ' away'}
                </span>
                {point.isOpen24h && (
                  <span className="spsugg-item-open">Open 24h</span>
                )}
              </div>

              <button
                className="spsugg-view-btn"
                onClick={() => handleViewOnMap(point)}
                aria-label={`View ${point.name} on map`}
              >
                <MapPin size={13} />
                <span>View</span>
              </button>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default SafePointSuggestions;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { MapPin, ShieldCheck } from 'lucide-react';
import './LocationPermissionScreen.css';

const LocationPermissionScreen = () => {
  const navigate = useNavigate();
  const [errorMsg, setErrorMsg] = useState('');

  const handleEnableLocation = () => {
    setErrorMsg('');
    if (!navigator.geolocation) {
      setErrorMsg('Geolocation is not supported by your browser.');
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        // Permission granted
        navigate('/app/home');
      },
      (error) => {
        // Permission denied or error
        setErrorMsg('Location permission is required for safe routing.');
      },
      {
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 0
      }
    );
  };

  const handleSkip = () => {
    navigate('/app/home');
  };

  return (
    <div className="location-perm-container">
      <div className="location-perm-glow" />

      <div className="location-perm-card">

        {/* Header */}
        <div className="location-perm-icon-wrapper">
          <MapPin size={36} strokeWidth={2.5} />
        </div>

        <div>
          <h1 className="location-perm-title">Enable Location</h1>
          <p className="location-perm-subtitle">
            SheShield uses your live location to calculate the safest routes, nearby police stations, hospitals, and emergency assistance.
          </p>
        </div>

        {/* Privacy Card */}
        <div className="location-privacy-box">
          <div className="location-privacy-title">
            <ShieldCheck size={18} />
            Your privacy matters.
          </div>
          <ul className="location-privacy-list">
            <li>Location is used only while navigating.</li>
            <li>Live location is shared only after SOS or when Alert Mode is enabled.</li>
            <li>We never track users unnecessarily.</li>
          </ul>
        </div>

        {/* Error Message */}
        {errorMsg && (
          <div className="location-error-msg">
            {errorMsg}
          </div>
        )}

        {/* Actions */}
        <div className="location-actions">
          {/* Note: We reuse login-btn styles since they are global-ish or we can just redefine them, 
              but it's better to just reuse the classes if they were global. Wait, .login-btn-primary is inside LoginScreen.css.
              Let's create matching local classes in LocationPermissionScreen.css or use inline for now.
              Actually, I can just use the identical styles. I will quickly add them to LocationPermissionScreen.css.
          */}
          <button type="button" className="location-btn-primary" onClick={handleEnableLocation}>
            Enable Location
          </button>
          <button type="button" className="location-btn-secondary" onClick={handleSkip}>
            Skip for now
          </button>
        </div>

      </div>
    </div>
  );
};

export default LocationPermissionScreen;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Shield, Eye, EyeOff } from 'lucide-react';
import axiosInstance from '../../../services/api/axiosInstance';
import useUserStore from '../../../stores/userStore';
import sheShieldLogo from '../../../assets/sheshield-logo.png';
import './LoginScreen.css';

const LoginScreen = () => {
  const navigate = useNavigate();

  // UI State
  const [isRegistering, setIsRegistering] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [successMessage, setSuccessMessage] = useState('');
  // Form State
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const setToken = useUserStore((s) => s.setToken);
  const setProfile = useUserStore((s) => s.setProfile);

  const getErrorMessage = (err, defaultMsg) => {
    if (err.response?.data) {
      const data = err.response.data;
      if (data.errors && Array.isArray(data.errors) && data.errors.length > 0) {
        return data.errors.map(e => e.message).join(' • ');
      }
      if (data.message && data.message !== 'Validation failed') {
        return data.message;
      }
    }
    return defaultMsg;
  };

  const handleLogin = async (e) => {
    if (e) e.preventDefault();

    setError('');
    setSuccessMessage('');
    setIsLoading(true);

    try {
      const res = await axiosInstance.post('/auth/login', { email, password });
      setToken(res.data.token);
      setProfile(res.data.user);
      navigate('/location');
    } catch (err) {
      setError(getErrorMessage(err, 'Login failed. Please check your credentials.'));
    } finally {
      setIsLoading(false);
    }
  };

  const handleRegister = async (e) => {
    e.preventDefault();

    setError('');
    setSuccessMessage('');
    setIsLoading(true);

    try {
      // 1. Register the user
      await axiosInstance.post('/auth/register', { name, email, phone, password });

      // 2. Switch to login view and show success message
      setIsRegistering(false);
      setName('');
      setPhone('');
      setEmail('');
      setPassword('');
      setSuccessMessage('Account created successfully. Please log in.');
      setIsLoading(false);
    } catch (err) {
      setError(getErrorMessage(err, 'Registration failed. Please try again.'));
      setIsLoading(false);
    }
  };

  const toggleMode = () => {
    setIsRegistering(!isRegistering);
    setError('');
    setSuccessMessage('');
    setName('');
    setPhone('');
    setEmail('');
    setPassword('');
  };

  return (
    <div className="login-container">
      <div className="login-background-glow" />

      <div className="login-card">

        {/* Header */}
        <div className="login-header">
          <div className="login-logo-container">
            <img src={sheShieldLogo} alt="SheShield Logo" className="login-brand-image" />
          </div>
          <h1 className="login-title">{isRegistering ? 'Create Account' : 'Welcome Back'}</h1>
          <p className="login-subtitle">
            {isRegistering ? 'Join SheShield for a safer journey.' : 'Navigate Safer. Stay Connected.'}
          </p>
        </div>

        {/* Form */}
        <form className="login-form" onSubmit={isRegistering ? handleRegister : handleLogin}>

          {isRegistering && (
            <>
              <div className="login-input-group">
                <label className="login-label">Full Name</label>
                <div className="login-input-wrapper">
                  <input
                    type="text"
                    className="login-input"
                    placeholder="Enter your full name"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    required={isRegistering}
                  />
                </div>
              </div>

              <div className="login-input-group">
                <label className="login-label">Phone Number</label>
                <div className="login-input-wrapper">
                  <input
                    type="tel"
                    className="login-input"
                    placeholder="Enter your phone number"
                    value={phone}
                    onChange={(e) => setPhone(e.target.value)}
                    required={isRegistering}
                  />
                </div>
              </div>
            </>
          )}

          <div className="login-input-group">
            <label className="login-label">Email</label>
            <div className="login-input-wrapper">
              <input
                type="email"
                className="login-input"
                placeholder="Enter your email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
            </div>
          </div>

          <div className="login-input-group">
            <label className="login-label">Password</label>
            <div className="login-input-wrapper">
              <input
                type={showPassword ? "text" : "password"}
                className="login-input"
                placeholder="Enter your password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
              <button
                type="button"
                className="login-password-toggle"
                onClick={() => setShowPassword(!showPassword)}
                aria-label={showPassword ? "Hide password" : "Show password"}
                tabIndex={-1}
              >
                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
              </button>
            </div>
          </div>

          {!isRegistering && (
            <div className="login-links">
              <button type="button" className="login-link">Forgot Password?</button>
            </div>
          )}

          {error && (
            <p style={{ color: 'var(--color-danger, #ff4d4d)', fontSize: '0.8rem', marginBottom: '0.5rem', textAlign: 'center', marginTop: isRegistering ? '1rem' : '0' }}>
              {error}
            </p>
          )}

          {successMessage && !isRegistering && (
            <p style={{ color: 'var(--color-success, #4ade80)', fontSize: '0.8rem', marginBottom: '0.5rem', textAlign: 'center' }}>
              {successMessage}
            </p>
          )}

          <div className="login-actions" style={{ marginTop: (isRegistering && !error) || (!isRegistering && !error && !successMessage) ? '1.5rem' : '0.5rem' }}>
            <button type="submit" className="login-btn-primary" disabled={isLoading}>
              {isLoading ? (isRegistering ? 'Creating Account…' : 'Signing in…') : (isRegistering ? 'Sign Up' : 'Login')}
            </button>
          </div>
        </form>

        {/* Footer */}
        <div className="login-footer">
          {isRegistering ? 'Already have an account? ' : "Don't have an account? "}
          <button type="button" className="login-link" onClick={toggleMode}>
            {isRegistering ? 'Log In' : 'Sign Up'}
          </button>
        </div>

      </div>
    </div>
  );
};

export default LoginScreen;

import React, { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './SplashScreen.css';
import sheShieldLogo from '../../../assets/sheshield-logo.png';

const SplashScreen = () => {
  const navigate = useNavigate();

  useEffect(() => {
    // Navigate to Login Screen after 2.5 seconds
    const timer = setTimeout(() => {
      navigate('/login');
    }, 2500);

    return () => clearTimeout(timer);
  }, [navigate]);

  return (
    <div className="splash-container">
      <div className="splash-background-glow" />

      <div className="splash-content">
        <div className="splash-brand-image-container">
          <img 
            src={sheShieldLogo} 
            alt="SheShield Logo" 
            className="splash-brand-image" 
          />
        </div>
        <p className="splash-tagline">Navigate Safer. Stay Connected.</p>
      </div>

      <div className="splash-loader" />
    </div>
  );
};

export default SplashScreen;

